const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const blackSeaPoint = ee.Geometry.Point([35.5, 43.5]); // A point in the central Black Sea
    const date1_start = '2022-05-19';
    const date1_end = '2022-05-21';
    const date2_start = '2022-06-19';
    const date2_end = '2022-06-21';
    const scale = 1000;

    // 2. Data Acquisition & Pre-processing Function
    const getBrightness = function(startDate, endDate, geometry) {
        // Use Sentinel-2 Level-2A data
        let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterBounds(geometry)
            .filterDate(startDate, endDate);

        if (collection.size().getInfo() === 0) {
            return null; // Signal no images found
        }

        // Function to mask clouds and keep only water pixels
        const maskCloudsAndWater = function(image) {
            const scl = image.select('SCL');
            // Keep only pixels classified as 'Water' (value 6)
            const waterMask = scl.eq(6);
            return image.updateMask(waterMask);
        };

        // Calculate brightness as the mean of RGB bands and apply mask
        const calculateBrightness = function(image) {
            // Sentinel-2 L2A surface reflectance values are scaled by 10000
            const brightness = image.select(['B4', 'B3', 'B2']).divide(10000).reduce(ee.Reducer.mean());
            return brightness.rename('brightness');
        };

        const image = collection.map(maskCloudsAndWater)
                                .map(calculateBrightness)
                                .mean(); // Mosaic by averaging available pixels

        // Check for valid pixels before reduction
        const pixelCount = image.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: geometry,
            scale: scale,
            maxPixels: 1e9
        }).get('brightness').getInfo();

        if (pixelCount === 0) {
            return { 'brightness': null, 'pixels': 0 };
        }

        const stats = image.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: geometry,
            scale: scale,
            maxPixels: 1e9
        });

        return { 'brightness': stats.get('brightness').getInfo(), 'pixels': pixelCount };
    };

    // 3. Calculation for both periods
    const mayResult = getBrightness(date1_start, date1_end, blackSeaPoint);
    const juneResult = getBrightness(date2_start, date2_end, blackSeaPoint);

    // 4. Validation and Output
    if (mayResult === null || juneResult === null) {
        console.log(`May 2022 images found: ${mayResult !== null}`);
        console.log(`June 2022 images found: ${juneResult !== null}`);
        console.log('Evidence: No images found for one or both periods.');
        console.log('A');
        return;
    }

    console.log(`May 20, 2022 Brightness: ${mayResult.brightness ? mayResult.brightness.toFixed(4) : 'N/A'}, Valid Pixels: ${mayResult.pixels}`);
    console.log(`June 20, 2022 Brightness: ${juneResult.brightness ? juneResult.brightness.toFixed(4) : 'N/A'}, Valid Pixels: ${juneResult.pixels}`);

    if (mayResult.pixels === 0 || juneResult.pixels === 0) {
        console.log('Evidence: Area was fully masked (e.g., by clouds) in one period.');
        console.log('C2');
        return;
    }

    if (mayResult.brightness === null || juneResult.brightness === null) {
        console.log('Evidence: Could not calculate a valid brightness value.');
        console.log('C3');
        return;
    }

    const increase = juneResult.brightness > mayResult.brightness;
    console.log(`Evidence: Brightness changed from ${mayResult.brightness.toFixed(4)} to ${juneResult.brightness.toFixed(4)}.`);

    if (increase) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    // A generic error might indicate incorrect names, methods, or other GEE issues.
    console.log('D');
});
